contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address x, uint v) public {
        require(x != address(this));
        // Case 1: single recipient with no code -> token call "succeeds" -> returns true.
        address[] memory tos1 = new address[](1);
        tos1[0] = x;
        uint[] memory vs1 = new uint[](1);
        vs1[0] = v;
        bool ok1;
        bool r1;
        try c.transfer(from, address(this), tos1, vs1) { r1 = false; } catch { r1 = true; }
        ok1 = !r1;
        // Case 2: second recipient is address(c), which has code -> our fallback reverts on it,
        // so the second transferFrom reverts and the whole transfer must revert.
        address[] memory tos2 = new address[](2);
        tos2[0] = x;
        tos2[1] = address(c);
        uint[] memory vs2 = new uint[](2);
        vs2[0] = v;
        vs2[1] = v;
        bool reverted2;
        try c.transfer(from, address(this), tos2, vs2) { reverted2 = false; } catch { reverted2 = true; }
        assert(ok1 && reverted2);
    }
    fallback(bytes calldata data) external payable returns (bytes memory) {
        // Mimic a token: succeed for recipients without code, revert otherwise.
        if (data.length >= 100) {
            address to = abi.decode(data[36:68], (address));
            if (to.code.length > 0) {
                revert();
            }
        }
        return abi.encode(true);
    }
    receive() external payable {}
}

